            if A[i][j]!=shape: B[i][j]=2
    # interior lines: count dashes strictly inside (not on border)
    for i in range(r0+1,r1):
        rr=runs(A[i],shape)
        interior_dashes=sum(1 for (a,b) in rr for j in range(a,b) if not border(i,j))
