                if A[i][j]!=shape: B[i][j]=2
    for j in range(c0+1,c1):
        rr=runs([A[i][j] for i in range(H)],shape)
        interior_dashes=sum(1 for (a,b) in rr for i in range(a,b) if not border(i,j))
        if interior_dashes>=2:
            for i in range(r0,r1+1):
                if A[i][j]!=shape: B[i][j]=2
    return B
